            box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1);
            transition: transform 0.2s ease;
        }

        .card-wrapper:hover { transform: translateY(-2px); }

        .light-mode .card-inner { background-color: var(--card-light); color: var(--text-primary-light); }
        .dark-mode .card-inner { background-color: var(--card-dark); color: var(--text-primary-dark); }

        .card-inner {
