        .dark-mode th { color: var(--text-secondary-dark); background-color: rgba(255,255,255,0.03); }

        .light-mode td { border-color: var(--border-light); }
        .dark-mode td { border-color: var(--border-dark); }

        tr:last-child td { border-bottom: none; }

        tr:hover td {
            filter: brightness(0.97);
        }
        .dark-mode tr:hover td { filter: brightness(1.1); } /* Slightly lighter on hover in dark */

        /* Specific Columns */
        .col-desc { font-weight: 500; }
