        .dark-mode .badge.paid::before { background-color: var(--status-paid-text-dark); box-shadow: 0 0 6px var(--status-paid-text-dark); }

        .dark-mode .badge.pending { background-color: var(--status-pending-bg-dark); color: var(--status-pending-text-dark); }
        .dark-mode .badge.pending::before { background-color: var(--status-pending-text-dark); box-shadow: 0 0 6px var(--status-pending-text-dark); }

        .dark-mode .badge.overdue { background-color: var(--status-overdue-bg-dark); color: var(--status-overdue-text-dark); }
        .dark-mode .badge.overdue::before { background-color: var(--status-overdue-text-dark); box-shadow: 0 0 6px var(--status-overdue-text-dark); }


        /* Footer / Totals */
        .invoice-footer {
            margin-top: auto;
            display: flex;
            justify-content: flex-end;
            padding-top: 24px;
        }

        .totals-box {
