        /* Responsive */
        @media (max-width: 768px) {
            .invoice-header { flex-direction: column; gap: 20px; }
            .header-actions { width: 100%; }
            .header-actions button { width: 100%; }
            .hide-mobile { display: none; }
        }
    </style>
</head>
